func IconSVG(name string) string {
	path, ok := materialSymbolPaths[name]
	if !ok {
		return ""
	}
	// The star's ink bounds are y=-743..-104 (center -423.5), while
	// its 960-unit canvas is centered at -480. Center the artwork without
	// moving the SVG box or changing the captured icon size.
	transform := ""
	if name == "star" {
		transform = ` transform="translate(0 -56.5)"`
	}
	return `<svg class="tokens-material-symbol" xmlns="http://www.w3.org/2000/svg" viewBox="0 -960 960 960" width="24" height="24" fill="currentColor" aria-hidden="true" focusable="false"><path` + transform + ` d="` + path + `"/></svg>`
}

// IconPath exposes the trusted bundled path for sprite composition.
func IconPath(name string) string { return materialSymbolPaths[name] }
